/**
 * Notifications that report the outcome of an action (`design/components/toast.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  SlotTemplate,
  derived,
  devWarning,
  getToasts,
  measured,
  mountEffect,
  removeToast,
  toast,
  uniqueId,
  useMember,
  watchEffect,
  type ToastAction,
} from '@polymorph/angular'

export interface ToasterMessages {
  dismiss: string
  notification: string
  viewport: string
}

/** Notifications that report the outcome of an action: the inputs it takes, by the React member's prop names. */
export interface ToastProps {
  /**
   * At most one; a shortcut, never the only way to do what it does. A call with an action that
   * sets neither `durationMs` nor `retained` is pinned, so a reader has the time to reach the
   * action.
   */
  action?: ToastAction
  description?: string
  /**
   * Required recovery actions stay reachable until their owning state resolves.
   */
  dismissible?: boolean
  /**
   * `Infinity` pins the toast until it is dismissed. A call that sets neither this nor
   * `retained` takes its tone's lifetime (see `retained`); one that sets only `retained` gets
   * `TOAST_DEFAULT_DURATION_MS`.
   */
  durationMs?: number
  /**
   * A live toast's id updates it in place: same card and position, new content, timer restarted.
   * An unknown id raises a new toast. `toast.promise` uses this, not a special path.
   */
  id?: string
  /**
   * State-owned notices are removed by their owner, never evicted by another notification. A
   * call that sets neither this nor `durationMs` takes its tone's lifetime: danger and warning
   * are retained and pinned, and the other tones leave after the default duration.
   */
  retained?: boolean
  title: string
  tone?: 'info' | 'warning' | 'success' | 'danger' | 'neutral'
}

/** Notifications that report the outcome of an action. */
@Component({
  selector: 'pm-toast',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="content" [pmSlotOf]="$"><ng-content select="[slot=content]" /></ng-template>
`,
})
export class Toast {
  /**
   * At most one; a shortcut, never the only way to do what it does. A call with an action that
   * sets neither `durationMs` nor `retained` is pinned, so a reader has the time to reach the
   * action.
   */
  readonly action = input<ToastProps['action']>(undefined)
  readonly description = input<ToastProps['description']>(undefined)
  /**
   * Required recovery actions stay reachable until their owning state resolves.
   */
  readonly dismissible = input<ToastProps['dismissible']>(undefined)
  /**
   * `Infinity` pins the toast until it is dismissed. A call that sets neither this nor
   * `retained` takes its tone's lifetime (see `retained`); one that sets only `retained` gets
   * `TOAST_DEFAULT_DURATION_MS`.
   */
  readonly durationMs = input<ToastProps['durationMs']>(undefined)
  /**
   * A live toast's id updates it in place: same card and position, new content, timer restarted.
   * An unknown id raises a new toast. `toast.promise` uses this, not a special path.
   */
  readonly id = input<ToastProps['id']>(undefined)
  /**
   * State-owned notices are removed by their owner, never evicted by another notification. A
   * call that sets neither this nor `durationMs` takes its tone's lifetime: danger and warning
   * are retained and pinned, and the other tones leave after the default duration.
   */
  readonly retained = input<ToastProps['retained']>(undefined)
  readonly title = input.required<ToastProps['title']>()
  readonly tone = input<ToastProps['tone']>(undefined)
  /**
   * Called once when the toast leaves for a reason other than its owner's: the reader dismissed
   * it, its time ran out, `toast.dismiss` closed it, or a newer toast evicted it. Removing it
   * (`remove`) and updating it in place do not call it, because the owner already knows.
   */
  readonly onDismiss = output<void>({ alias: 'dismiss' })
  protected readonly $ = useMember({
    events: ['dismiss'],
    props: {
      action: () => this.action(),
      description: () => this.description(),
      dismissible: () => this.dismissible(),
      durationMs: () => this.durationMs(),
      id: () => this.id(),
      retained: () => this.retained(),
      title: () => this.title(),
      tone: () => this.tone(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly toastId = derived(() => this.$p.id ?? this.uid)
  protected readonly options = measured(() => ({
    id: this.toastId.value,
    title: this.$p.title,
    description: this.$p.description,
    tone: this.$p.tone,
    action: this.$p.action,
    durationMs: this.$p.durationMs,
    dismissible: this.$p.dismissible,
    retained: this.$p.retained,
    content: this.$.template('content'),
    onDismiss: () => this.$.emit(this.onDismiss, 'onDismiss'),
  }))
  private release1: (() => void) | undefined
  private release3: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => [this.toastId.value, this.$p.title],
      () => this.effect1(),
      true,
    )
    watchEffect(
      () => this.options.value,
      () => this.effect2(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  private effect1(): void {
    this.release1?.()
    const ran = toast(this.options.value)
    this.release1 = () => {
      removeToast(ran)
    }
  }

  private effect2(): void {
    void (
      getToasts().some((record) => record.id === this.toastId.value && record.closing !== true) &&
      toast(this.options.value)
    )
  }

  private effect3(): void {
    this.release3?.()
    const timer = setTimeout(() => {
      devWarning(
        document.querySelector('[data-toast-part="list"]') === null,
        `Toast "${this.$p.title}" rendered with no Toast viewport mounted, so nothing draws it. Mount the viewport once at the application root, outside any error boundary whose fallback renders a Toast.`,
      )
    }, 0)
    this.release3 = () => clearTimeout(timer)
  }
}
